29	    <section
30	      aria-label={t("browse.filtersHeading")}
31	      className="flex flex-col gap-4 rounded-card border border-border bg-surface p-5"
32	    >
33	      <div className="grid grid-cols-3 gap-4 max-md:grid-cols-1">
34	        <Field label={t("browse.topicLabel")}>
35	          {(p) => (
36	            <Select
37	              {...p}
38	              value={params.get("topic") ?? ""}
39	              onChange={(e) => update("topic", e.target.value)}
40	            >
41	              <option value="">{t("browse.anyTopic")}</option>
42	              {TOPICS.map((topic) => (
