60	                <option key={lang} value={lang}>
61	                  {lang}
62	                </option>
63	              ))}
64	            </Select>
65	          )}
66	        </Field>
67	
68	        <Field label={t("browse.priceLabel")}>
69	          {(p) => (
70	            <Select
71	              {...p}
72	              value={params.get("maxPrice") ?? ""}
73	              onChange={(e) => update("maxPrice", e.target.value)}
74	            >
75	              <option value="">{t("browse.anyPrice")}</option>
76	              {PRICE_TIERS.map((cents) => (
77	                <option key={cents} value={cents}>
78	                  {`$${cents / 100}`}
79	                </option>
80	              ))}
81	            </Select>
82	          )}
83	        </Field>
84	      </div>
85	
86	      <div className="flex flex-wrap items-center justify-between gap-4">
87	        <label className="flex items-center gap-3 text-base font-bold text-ink">
88	          <input
89	            type="checkbox"
90	            checked={params.get("available") === "1"}
91	            onChange={(e) => update("available", e.target.checked ? "1" : "")}
92	            className="size-5"
93	          />
94	          {t("browse.availableNowLabel")}
95	        </label>
96	        {hasFilters ? (
97	          <Button variant="quiet" onClick={() => router.push("/browse")}>
98	            {t("browse.clearFilters")}
99	          </Button>
